func shortID(id string) string {
	if len(id) > 8 {
		return id[:8]
	}
	return id
}

func scalingModeLabel(mode string) string {
	switch mode {
	case "hpa":
		return "HPA"
	case "keda_cron":
		return "KEDA cron"
	case "keda_http":
		return "KEDA HTTP"
	default:
		return mode
	}
}

